// Dim an LED from a potentiometer
const uint8_t POT_PIN = 1;                 // wiper of the 10 kΩ pot, GPIO1
const uint8_t LED_PIN = 4;
const uint8_t RGB_PIN = 38;
const uint32_t PWM_HZ = {{p:pwmHz}};
const uint8_t PWM_BITS = 8;                // 8 bits: duty 0 to 255

unsigned long lastPrint = 0;

void setup() {
  Serial.begin(115200);
  analogReadResolution(12);                // 12-bit ADC: raw 0 to 4095
  ledcAttach(LED_PIN, PWM_HZ, PWM_BITS);   // 3.x API: attach PWM by pin
}

void loop() {
  int raw = analogRead(POT_PIN);           // 0 at one end of the knob, 4095 at the other
  int mv = analogReadMilliVolts(POT_PIN);
  int duty = raw / 16;                     // 4095 / 16 = 255, full duty
  ledcWrite(LED_PIN, duty);
  rgbLedWrite(RGB_PIN, duty / 4, 0, (255 - duty) / 4);
  if (millis() - lastPrint >= 250) {
    lastPrint = millis();
    Serial.printf("pot %d (%d mV) -> duty %d\n", raw, mv, duty);
  }
  delay(10);
}

